business as (select
    CAST(greatest(co.source_published_at,em.source_published_at,tm.source_published_at,a.source_published_at,s.src_published_at) AS Nullable(DateTime64(3,'UTC'))) AS `source_published_at`,
    CAST(arraySort(arrayDistinct(arrayFilter(x->x is not null,arrayConcat(ifNull(co.source_version_keys,[]),ifNull(em.source_version_keys,[]),ifNull(tm.source_version_keys,[]),ifNull(a.source_version_keys,[]),[s.source_version_key])))) AS Array(String)) AS `source_version_keys`,
    CAST(lower(hex(SHA256(toJSONString(materialize(tuple('action_v1',tuple('tenant_id','String',if(isNull(s.src_tenant_id),'1','0'),ifNull(toString(s.src_tenant_id),'')),tuple('action_id','Int64',if(isNull(s.src_id),'1','0'),ifNull(toString(s.src_id),'')))))))) AS String) AS `action_key`,
    CAST(lower(hex(SHA256(toJSONString(materialize(tuple('action_version_v1',tuple('action_key','String',if(isNull(action_key),'1','0'),ifNull(toString(action_key),'')),tuple('valid_from_at','DateTime64(3,\'UTC\')',if(isNull(s.boundary),'1','0'),ifNull(toString(toUnixTimestamp64Milli(s.boundary)),'')))))))) AS String) AS `action_version_key`,
    CAST(s.src_tenant_id AS String) AS `tenant_id`,
    CAST(s.src_id AS Int64) AS `action_id`,
    CAST(s.boundary AS DateTime64(3,'UTC')) AS `valid_from_at`,
    CAST(s.slice_end AS Nullable(DateTime64(3,'UTC'))) AS `valid_to_at`,
    CAST(s.src_published_at AS DateTime64(3,'UTC')) AS `source_action_published_at`,
    CAST(s.src_is_deleted AS Bool) AS `is_source_deleted`,
    CAST(s.src_type_id AS Nullable(Int64)) AS `action_type_id`,
    CAST(a.action_type_key AS Nullable(String)) AS `action_type_key`,
    CAST(a.action_type_version_key AS Nullable(String)) AS `action_type_version_key`,
    CAST(s.src_company_id AS Nullable(Int64)) AS `company_id`,
    CAST(co.company_key AS Nullable(String)) AS `company_key`,
    CAST(co.company_version_key AS Nullable(String)) AS `company_version_key`,
    CAST(if(s.src_depends_on_type='contact',s.src_depends_on_id,NULL) AS Nullable(Int64)) AS `contact_id`,
    CAST(if(s.src_depends_on_type='opportunity',s.src_depends_on_id,NULL) AS Nullable(Int64)) AS `opportunity_id`,
    CAST(if(opportunity_id is not null,lower(hex(SHA256(toJSONString(materialize(tuple('opportunity_v1',tuple('tenant_id','String',if(isNull(s.src_tenant_id),'1','0'),ifNull(toString(s.src_tenant_id),'')),tuple('opportunity_id','Int64',if(isNull(opportunity_id),'1','0'),ifNull(toString(opportunity_id),'')))))))),NULL) AS Nullable(String)) AS `opportunity_key`,
    CAST(s.src_depends_on_type AS String) AS `depends_on_type`,
    CAST(s.src_depends_on_id AS Nullable(Int64)) AS `depends_on_id`,
    CAST(s.src_main_manager_id AS Nullable(Int64)) AS `employee_id`,
    CAST(em.employee_key AS Nullable(String)) AS `employee_key`,
    CAST(em.employee_version_key AS Nullable(String)) AS `employee_version_key`,
    CAST(tm.team_key AS Nullable(String)) AS `team_key`,
    CAST(tm.team_version_key AS Nullable(String)) AS `team_version_key`,
    CAST(tm.team_key is not null AS Bool) AS `is_team_calculable`,
    CAST(s.src_created_at AS Nullable(DateTime64(3,'UTC'))) AS `created_at`,
    CAST(s.src_started_at AS Nullable(DateTime64(3,'UTC'))) AS `scheduled_start_at`,
    CAST(s.src_ended_at AS Nullable(DateTime64(3,'UTC'))) AS `scheduled_end_at`,
    CAST(NULL AS Nullable(DateTime64(3,'UTC'))) AS `actual_event_at`,
