    c.`depends_on_type` AS `depends_on_type`,
    c.`depends_on_id` AS `depends_on_id`,
    c.`employee_id` AS `employee_id`,
    c.`employee_key` AS `employee_key`,
    c.`employee_version_key` AS `employee_version_key`,
    c.`team_key` AS `team_key`,
    c.`team_version_key` AS `team_version_key`,
    c.`is_team_calculable` AS `is_team_calculable`,
    c.`created_at` AS `created_at`,
    c.`scheduled_start_at` AS `scheduled_start_at`,
    c.`scheduled_end_at` AS `scheduled_end_at`,
    c.`actual_event_at` AS `actual_event_at`,
    c.`realization_status` AS `realization_status`,
    c.`is_demo_request` AS `is_demo_request`,
    c.`is_demo_type` AS `is_demo_type`,
    c.`is_realized_demo` AS `is_realized_demo`,
    c.`demo_session_key` AS `demo_session_key`,
    c.`counting_date` AS `counting_date`,
    c.`link_status` AS `link_status`,
    c.`calculation_status` AS `calculation_status`,
    c.`status_reason` AS `status_reason`
from candidate c
{% if is_incremental() %}
left join (select model_run_id,record_key,row_hash from {{ this }} where model_run_id={{ ch_literal(var('model_run_id','parse_only')) }}) t on c.model_run_id=t.model_run_id and c.record_key=t.record_key
where if(t.record_key is null,true,throwIf(c.row_hash!=t.row_hash,'Immutable run content diverged')!=0)
{% endif %}
